  "produtor musical",
  "estudio de gravacao",
  "show ao vivo",
  "palco",
  "microfone",
  "ensaio",
  "ensaio aberto"
];

const sites = [
  "site:instagram.com",
  "site:facebook.com"
];

const extras = [
  "whatsapp",
  "contato",
  "telefone",
  "agenda",
  "show",
  "evento",
  "casamento",
  "festa",
  "booking"
];

const queries = [];

// Busca 1: nicho + whatsapp + site
for (const nicho of nichos) {
  for (const site of sites) {
    queries.push({ q: `"${nicho}" "whatsapp" ${site}`, start: 0 });
  }
}

// Busca 2: nicho + contato + site
for (const nicho of nichos.slice(0, 20)) {
  for (const site of sites) {
    queries.push({ q: `"${nicho}" "contato" ${site}`, start: 0 });
  }
}

// Busca 3: nicho + telefone + site
for (const nicho of nichos.slice(0, 15)) {
  for (const site of sites) {
    queries.push({ q: `"${nicho}" "telefone" ${site}`, start: 0 });
  }
}

// Busca 4: nicho + evento/casamento + whatsapp
for (const nicho of nichos.slice(0, 10)) {
  queries.push({ q: `"${nicho}" "casamento" "whatsapp" site:instagram.com`, start: 0 });
  queries.push({ q: `"${nicho}" "festa" "whatsapp" site:instagram.com`, start: 0 });
}

// Busca 5: termos específicos brasileiros
const brTerms = [
  "banda para festa",
  "cantor para evento",
  "dj para casamento",
  "musico para bar",
  "show particular",
  "agenda de shows",
  "contratar banda",
  "contratar cantor",
  "contratar dj"
];
for (const term of brTerms) {
  queries.push({ q: `"${term}" "whatsapp" site:instagram.com`, start: 0 });
  queries.push({ q: `"${term}" "whatsapp" site:facebook.com`, start: 0 });
}

// Exemplo para limitar a 50 buscas por execução
return queries.slice(0, 50).map(q => ({ json: q }));

// Pega TODOS os resultados do nó "Busca raspagem de dados"
const allApiResponses = $('Busca raspagem de dados').all();

const items = [];
const seen = new Set();


function sanitizeNome(nome) {
  if (!nome) return null;
  // Remove caracteres não-ASCII e emojis
  return nome
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[^�-]/g, '')
    .replace(/[🟢🚨▶️🎵🎶📱💰✨🏆🎸🎤🎧📢🔊💬👥🎥📽️🎬🎞️]/g, '')
    .replace(/\s+/g, ' ')
    .trim()
    .substring(0, 200);
}

function extrairNomeDoTitle(title) {
  if (!title) return null;

  // Remove tudo depois de certas palavras-chave
  let nome = title
    .split(/WhatsApp|whatsapp|WHATSAPP|Telefone|telefone|TELEFONE|Contato|contato|CONTATO|Booking|booking|Shows|shows|SHOWS/)[0]
    .trim();

  // Remove frases comuns que não são nomes
  nome = nome
    .replace(/^(RECEBEMOS NO WHATSAPP|Chegou a comunidade|Mande seu som|Central de fãs|Grupo de whatsapp|TO SEM BANDA|Tô sem banda|Procura-se vocalista|Add o nosso número de WhatsApp|no meu WhatsApp|para formar banda|para musicos e cantores)\s*[!🚨\-]*\s*/i, '')
    .replace(/\s*\|.*$/, '')
    .replace(/\s*\-.*$/, '')
    .replace(/[🟢🚨▶️🎵🎶📱💰✨🏆🎸🎤🎧📢🔊💬👥🎥📽️🎬🎞️]/g, '')
    .replace(/\s+/g, ' ')
    .trim();

  if (nome.length < 3) return null;
  nome = nome.replace(/^whatsapp\s+/i, '');

  // Trunca em 250 caracteres
  return nome.substring(0, 250) || null;
}

function extrairNomeDoSource(source) {
  if (!source) return null;
  const match = source.match(/·\s*(.+)$/);
  if (match) return match[1].trim();
  if (source === 'Facebook' || source === 'Instagram') return null;
  return source.trim();
}

const rePhone = /(\+55\s*)?\(?(\d{2})\)?[\s\-]?(\d{4,5})[\s\-]?(\d{4})(?!\d)/g;

function extrairWhatsapp(texto) {
  if (!texto) return null;
  let match;
  while ((match = rePhone.exec(texto)) !== null) {
    let ddd = match[2];
    let parte1 = match[3];
    let parte2 = match[4];
    if (parte1.length >= 4) {
      return `55${ddd}${parte1}${parte2}`;
    }
  }
  return null;
}

const reWaMe = /wa\.me\/([a-zA-Z][a-zA-Z0-9._-]{1,})/;

// Processa CADA resposta da API
for (const apiItem of allApiResponses) {
  const apiResponse = apiItem.json;
 const results = apiResponse.organic || [];
  const currentQuery = apiResponse.q || apiResponse.search_parameters?.q || '';

  for (const r of results) {
    const title = r.title ?? '';
    const link = r.link ?? '';
    const snippet = r.snippet ?? '';

    let nome_perfil = null;
    if (r.channel && r.channel.trim()) {
      nome_perfil = r.channel.trim();
    }
    if (!nome_perfil && r.source) {
      nome_perfil = extrairNomeDoSource(r.source);
    }
    if (!nome_perfil) {
      nome_perfil = extrairNomeDoTitle(title);
    }
    if (!nome_perfil || nome_perfil.length < 2) continue;

    if (['Facebook', 'Instagram', 'WhatsApp', 'Portal da Música', 'Podcast do Lambadão'].includes(nome_perfil)) {
      continue;
    }

    let whatsapp = extrairWhatsapp(title) || extrairWhatsapp(snippet) || extrairWhatsapp(link);
    let wa_username = null;
    const mWaMe = link.match(reWaMe);
    if (mWaMe) wa_username = mWaMe[1].split('?')[0];

    if (!whatsapp && !wa_username) continue;

    const chave = wa_username ?? whatsapp ?? nome_perfil.toLowerCase();
    if (seen.has(chave)) continue;
    seen.add(chave);

    items.push({
      json: {
        nome_perfil: sanitizeNome(nome_perfil),
        wa_username: wa_username || null,
        whatsapp: whatsapp || null,
        link_whatsapp: wa_username ? `https://wa.me/${wa_username}` : (whatsapp ? `https://wa.me/${whatsapp}` : null),
        snippet: (snippet || '').slice(0, 300),
        fonte_url: link,
        original_query: currentQuery,
        extraido_em: new Date().toISOString(),
      }
    });
  }
}

return items;

const items = $input.all();

if (items.length === 0) {
  return [{ json: { debug: 'nenhum_item_recebido', whatsapp: null } }];
}

return items.map(item => {
  let raw = item.json.link_whatsapp || item.json.snippet || '';
  let cleaned = raw.replace(/\D/g, '');

  if (cleaned.length === 10) cleaned = '55' + cleaned;
  if (cleaned.length === 11 && !cleaned.startsWith('55')) cleaned = '55' + cleaned;

  if (!cleaned.startsWith('55') || cleaned.length < 12) {
    cleaned = null;
  }

  return {
    json: {
      ...item.json,
      whatsapp: cleaned
    }
  };
}).filter(i => i.json.whatsapp !== null && i.json.whatsapp !== '');

const serp = $input.first().json;
const next = serp.serpapi_pagination?.next;
const currentQ = $input.first().json.q || '';

if (next) {
  const match = next.match(/start=(\d+)/);
  if (match) {
    return [{ json: { continuar: true, start: parseInt(match[1]), q: currentQ } }];
  }
}
return [{ json: { continuar: false } }];
